import {escapeHtml as esc} from './core.mjs';
import {COMPANY,LEGAL,LEGAL_LINKS,companyMarkup,legalLinksMarkup,checkoutSummaryMarkup} from './legal.mjs';
import {billingMarkup} from './card-ui.mjs';
export async function api(path,options={}){
 if(globalThis.mentraNative&&path==='logout'){globalThis.mentraNativeCalendar?.cancel();await globalThis.mentraNativePush?.unsubscribe();await globalThis.mentraNativeClearCache?.();}
 const r=await (globalThis.mentraNativeApi?globalThis.mentraNativeApi(path,{...options,headers:{'Content-Type':'application/json',...options.headers}}):fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}}));
 let b;try{b=await r.json();}catch{throw Error('Servidor indisponível.');}
 if(!r.ok)throw Object.assign(Error(b.error||'Falha na operação.'),{status:r.status});
 if(globalThis.mentraNative){if(path==='me'&&b.user?.id)globalThis.mentraNativeUserId=b.user.id;if(path==='logout'){globalThis.mentraNativeUserId=null;globalThis.mentraPlatform=null;}}
 return b;
}
const brl=c=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const brlShort=c=>c%100===0?(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:0,maximumFractionDigits:0}):brl(c);
export const periodLabel=days=>({30:'mês',90:'trimestre',365:'ano'})[days||30]||`período de ${days} dias`;
export const PROMO_FINE_PRINT='Valor promocional válido somente para o primeiro período contratado (primeiro mês, trimestre ou ano). Após esse período, a renovação é feita pelo valor regular do plano.';
export const formatPlanPrice=p=>p.priceCents===null||p.priceCents===undefined?'Preço em definição':brl(p.priceCents)+' / '+periodLabel(p.days);
// chargeCents comes from the server: what this person would pay now (promotional only before a first payment).
export const planCharge=p=>p.chargeCents??p.priceCents??null;
export function planPriceMarkup(p){
 if(p.priceCents===null||p.priceCents===undefined)return '<p class="plan-price"><strong>Preço em definição</strong></p>';
 const charge=planCharge(p),per=periodLabel(p.days);
 if(charge<p.priceCents)return `<p class="plan-price promo"><span class="plan-price-from">De <s>${brl(p.priceCents)}</s></span> <span class="plan-price-now">por <strong>${brlShort(charge)}</strong></span> <small>no primeiro ${per}</small></p>`;
 return `<p class="plan-price"><strong>${brl(p.priceCents)}</strong> <small>/ ${per}</small></p>`;
}
const finePrint=plans=>plans.some(p=>p.promoPriceCents)?`<p class="plan-fineprint">${PROMO_FINE_PRINT}</p>`:'';
export const subscriptionLabel=status=>({active:'Ativo',pending:'Aguardando ativação',canceled:'Cancelado',expired:'Expirado'})[status]||status;
export const send=(path,data,method='POST',options={})=>api(path,{...options,method,body:JSON.stringify(data)});
function showRecovery(root,code,mode='recover'){root.innerHTML=`<main id="main-content" class="portal" tabindex="-1"><section class="card"><h1>Guarde seu código de recuperação.</h1><p>Este código permite recuperar sua conta se esquecer a senha. Ele será exibido somente agora. Guarde em um lugar seguro fora deste aparelho e não compartilhe.</p><code id="recovery-code-value" style="display:block;overflow-wrap:anywhere;padding:20px;background:#eef2e9">${esc(code)}</code><p id="recovery-copy-status" role="status" aria-live="polite"></p><div class="button-row" style="display:flex;gap:10px;flex-wrap:wrap;margin:12px 0"><button type="button" class="outline" id="recovery-copy">Copiar código</button><button type="button" class="outline" id="recovery-download">Baixar código (.txt)</button></div><p>Ao recuperar a conta, o código será substituído por um novo.</p><button class="primary" id="recovery-continue">Já guardei. Continuar</button></section></main>`;const status=root.querySelector('#recovery-copy-status');root.querySelector('#recovery-copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);status.textContent='Código copiado. Cole em um gerenciador de senhas ou local seguro.';}catch{status.textContent='Selecione o código acima e copie manualmente.';}};root.querySelector('#recovery-download').onclick=()=>{const url=URL.createObjectURL(new Blob([`Mentra Life — Código pessoal de recuperação\n\n${code}\n\nGuarde em local seguro e não compartilhe.\n`],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mentra-codigo-recuperacao.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Arquivo de recuperação gerado.';};root.querySelector('#recovery-continue').onclick=()=>{if(mode==='recover'){try{sessionStorage.setItem('mentra-auth-notice',JSON.stringify({message:'Conta recuperada. Entre com a nova senha que você definiu.',at:Date.now()}));}catch{}}location.reload();};}
export function recoveryForm(root,returnPath='/'){root.innerHTML=`<main id="main-content" class="portal" tabindex="-1"><section class="card portal-access"><div><h1>Recupere seu acesso.</h1><p>Use o código entregue ao criar sua conta. Sua senha será substituída e os dispositivos conectados sairão da conta.</p><a href="${returnPath==='/admin'?(globalThis.mentraNative?'/admin.html':'/admin'):'/'}">Voltar ao login</a></div><form id="recovery-form"><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Código de recuperação<input name="recoveryCode" required minlength="64" maxlength="64" autocomplete="off"></label><label>Nova senha<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p role="alert" id="recovery-error"></p><button class="primary" type="submit">Recuperar conta</button></form></section></main>`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const result=await send('recover',Object.fromEntries(new FormData(e.target)));showRecovery(root,result.recoveryCode);}catch(error){root.querySelector('#recovery-error').textContent=error.message;b.disabled=false;}};}
export async function startPlatform(){
 const root=document.querySelector('#app');let me;try{me=await api('me');}catch(e){if(e.status!==401){root.innerHTML=`<main id="main-content" class="portal" tabindex="-1"><h1>Mentra Life</h1><p>${esc(e.message)}</p><button id="retry-platform">Tentar novamente</button></main>`;root.querySelector('#retry-platform').onclick=()=>location.reload();return null;}}
 if(!me){await portal(root);return null;}
 const saved=await api('state');return {...me,...saved};
}
async function portal(root){
 const {plans,paymentsConfigured}=await api('plans');let mode='login',selected=plans[0].id;
 function render(){root.innerHTML=`<div class="portal"><header class="portal-nav"><a href="/" class="portal-brand"><img src="assets/mentra-logo-256.webp" width="256" height="256" alt="">mentra <small>LIFE</small></a><a id="open-auth" href="#acesso">Acessar minha conta →</a></header><main id="main-content" tabindex="-1"><section class="portal-hero"><div><p class="eyebrow">UM LUGAR PARA SUA VIDA</p><h1>Sua vida,<br><em>mais leve.</em></h1><p>Organize o dia, cuide do seu dinheiro e transforme ideias em próximos passos. Sua Mentra acompanha você.</p><a class="primary" href="#planos">Encontre seu plano →</a></div><img src="assets/mentra-face-hero.webp" width="768" height="768" fetchpriority="high" alt="Mentra, sua assistente pessoal"></section><section class="portal-benefits">${[['Rotina com clareza','Agenda, tarefas e prioridades no seu ritmo.'],['Dinheiro organizado','Contas, lançamentos, compromissos e relatórios.'],['Ideias em movimento','Planos editáveis para começar e acompanhar.'],['Documentos à mão','Recibos em PDF e biblioteca de documentos.']].map(([t,d])=>`<article><h2>${t}</h2><p>${d}</p></article>`).join('')}</section><section id="planos"><p class="eyebrow">ESCOLHA SEU PERÍODO</p><h2>Acesso completo à Mentra, no período que preferir.</h2><p>Um único plano com todos os recursos e a mesma capacidade de IA. Você escolhe por quanto tempo quer liberar o acesso.</p><div class="portal-plans">${plans.map((p,i)=>`<article class="card ${i===1?'featured':''}"><p class="eyebrow">${p.days?`${p.days} DIAS DE ACESSO`:'MENTRA LIFE'}</p><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p>${storeApp()?'':planPriceMarkup(p)}<ul><li>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA por mês</li><li>Agenda, tarefas e documentos</li><li>Finanças e recibos em PDF</li><li>Impulso e bem-estar</li><li>Painel individual</li></ul><button class="${i===1?'primary':'outline'}" data-plan="${p.id}">Escolher o plano ${esc(p.name)}</button></article>`).join('')}</div>${storeApp()?'':finePrint(plans)}<p>${storeApp()?'Crie sua conta para começar. Os recursos do seu plano acompanham a sua conta Mentra.':paymentsConfigured?'Crie uma conta e pague com PIX para ativar seu plano.':'Cadastro disponível. A contratação e a ativação serão liberadas após a configuração dos pagamentos.'}</p></section><section class="portal-access card" id="acesso"><div><p class="eyebrow">SEU ESPAÇO</p><h2>${mode==='register'?'Comece com um pouco de clareza.':'Que bom ter você de volta.'}</h2><p>Seus dados ficam associados exclusivamente à sua conta.</p><button class="text-link" id="switch-auth">${mode==='register'?'Já tenho uma conta':'Quero criar uma conta'}</button></div><form id="auth-form">${mode==='register'?'<label>Seu nome<input name="name" autocomplete="name" maxlength="80" required></label>':''}<label>E-mail<input name="email" type="email" autocomplete="email" required></label><label>Senha<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="12" maxlength="128" required><small>Use pelo menos 12 caracteres.</small></label>${mode==='register'?`<label>Seu plano<select name="plan">${plans.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}${p.days?` · ${p.days} dias`:''}</option>`).join('')}</select></label><label class="legal-accept"><input type="checkbox" name="acceptTerms" value="1" required><span>Tenho ${LEGAL.minimumAge} anos ou mais, li e aceito os <a href="${LEGAL_LINKS.terms}" target="_blank" rel="noopener">Termos de Uso</a> e li o <a href="${LEGAL_LINKS.privacy}" target="_blank" rel="noopener">Aviso de Privacidade</a>.</span></label>`:''}<p id="auth-error" role="alert"></p><button class="primary" type="submit">${mode==='register'?'Criar minha conta':'Entrar'}</button></form></section></main><footer>Mentra Life · Um passo de cada vez. <a href="mailto:${esc(COMPANY.email)}">Contato e suporte</a>${companyMarkup({heading:'',compact:true})}${legalLinksMarkup()}</footer></div>`;
 const recoveryButton=document.createElement('button');recoveryButton.type='button';recoveryButton.className='text-link auth-recovery';recoveryButton.textContent='Recuperar acesso com meu código';recoveryButton.onclick=()=>recoveryForm(root);root.querySelector('#auth-form').append(recoveryButton);
 try{const raw=sessionStorage.getItem('mentra-auth-notice');if(raw){sessionStorage.removeItem('mentra-auth-notice');const note=JSON.parse(raw);if(Date.now()-note.at<120000){const box=root.querySelector('#auth-error');if(box){box.textContent=note.message;box.classList.add('auth-success');box.setAttribute('role','status');}}}}catch{}
 root.querySelector('#open-auth').onclick=e=>{e.preventDefault();mode='login';render();root.querySelector('#acesso').scrollIntoView({block:'start'});};
 root.querySelector('#switch-auth').onclick=()=>{mode=mode==='register'?'login':'register';render();root.querySelector('#acesso').scrollIntoView({block:'start'});};
 root.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{selected=b.dataset.plan;mode='register';render();root.querySelector('#acesso').scrollIntoView({behavior:'smooth'});});
 root.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await send(mode==='register'?'register':'login',Object.fromEntries(new FormData(e.target)));if(mode==='register'&&!globalThis.mentraNative)history.replaceState(null,'','#/planos');if(result.recoveryCode){showRecovery(root,result.recoveryCode,mode==='register'?'register':'recover');return;}location.reload();}catch(error){root.querySelector('#auth-error').textContent=error.message;button.disabled=false;}};
 }render();
}
const dateBR=ms=>new Date(ms).toLocaleDateString('pt-BR');
const dateTimeBR=ms=>new Date(ms).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
function consentRow(kind,granted,title,text){return `<div class="consent-row"><div><h3>${title}</h3><p class="account-effect">${text}</p><p class="form-help">${granted?'Autorizado.':'Não autorizado.'}</p></div><button class="${granted?'outline':'primary'}" data-consent="${kind}" data-value="${granted?'false':'true'}">${granted?'Revogar autorização':'Autorizar'}</button></div>`;}
function withdrawalMarkup(w){
 if(w?.request)return `<p>Pedido registrado em ${esc(dateTimeBR(w.request.requestedAt))}. Protocolo <strong>${esc(w.request.protocol)}</strong>, valor de ${esc(brl(w.request.amount))}. ${w.request.status==='refunded'?'O estorno foi feito para a conta de onde saiu o PIX.':`O estorno está sendo concluído pela nossa equipe em até ${LEGAL.refundBusinessDays} dias úteis.`}</p>`;
 if(w?.eligible)return `<p class="account-effect">Efeito: o valor de ${esc(brl(w.eligible.amount))} volta integralmente para a conta de onde saiu o PIX, e os dias liberados por esse pagamento saem do seu acesso. O prazo vai até ${esc(dateTimeBR(w.eligible.deadline))}.</p><form id="platform-withdraw" class="form-stack"><label class="check-field"><input type="checkbox" name="confirm" required><span>Quero desistir desta compra e receber o valor de volta.</span></label><button class="outline danger" type="submit">Desistir da compra</button></form>`;
 return `<p class="account-effect">Você pode desistir em até ${LEGAL.withdrawalDays} dias após cada pagamento e receber o valor de volta. No momento, não há pagamento dentro desse prazo.</p>`;
}
export function aboutMarkup(){return `<section class="card account-about" id="sobre"><span class="eyebrow">SOBRE E CONTATO</span><h2>Mentra Life</h2>${companyMarkup({heading:'',compact:true})}<p class="form-help">Atendimento também pelo botão Feedback. Pedidos sobre dados pessoais: ${esc(COMPANY.dpoEmail||COMPANY.email)}.</p>${legalLinksMarkup()}<p class="form-help">Termos de Uso, versão ${esc(LEGAL.termsVersion)}. Aviso de Privacidade, versão ${esc(LEGAL.privacyVersion)}.</p></section>`;}
export function accountMarkup(platform,preferences=''){
 const user=platform.user,sub=platform.subscription||{},active=sub.status==='active'&&(!sub.current_period_end||sub.current_period_end>Date.now());
 const terms=user.termsAccepted===false?`<section class="card legal-update"><span class="eyebrow">DOCUMENTOS ATUALIZADOS</span><h2>Leia e aceite os Termos de Uso</h2><p>Publicamos a versão ${esc(LEGAL.termsVersion)} dos <a href="${LEGAL_LINKS.terms}">Termos de Uso</a> e do <a href="${LEGAL_LINKS.privacy}">Aviso de Privacidade</a>.</p><button class="primary" data-consent="terms" data-value="true">Li e aceito os Termos de Uso</button></section>`:'';
 const renewal=sub.current_period_end&&active?`Seu acesso pago vai até ${esc(dateBR(sub.current_period_end))}. Depois disso, nada é cobrado: as funções pagas ficam bloqueadas e seus dados continuam guardados.`:active?'Seu acesso foi liberado pela administração, sem data final e sem cobrança.':'Você não tem um período pago ativo. Nada é cobrado automaticamente.';
 return `<div class="page-heading"><div><p class="eyebrow">MEU ESPAÇO</p><h1>Seu jeito de seguir em frente.</h1><p class="subtitle">${esc(user.name)} · ${esc(user.email)}</p></div></div><div class="account-layout"><div class="account-main">${terms}${preferences}${user.role==='admin'?'<section class="card"><p class="eyebrow">ADMIN MASTER</p><h2>Administração da Mentra</h2><p>Gerencie os planos, contas e acessos.</p><a class="primary" href="'+(globalThis.mentraNative?'/admin.html':'/admin')+'">Abrir painel administrativo</a></section>':''}`+
 `<section class="card account-security"><div class="section-head"><div><span class="eyebrow">ACESSO</span><h2>Segurança da conta</h2></div></div><details class="account-disclosure"><summary><span>Alterar senha<small>Proteja o acesso à sua conta.</small></span><span aria-hidden="true">＋</span></summary><form id="platform-password" class="form-stack"><label>Senha atual<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nova senha<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="form-help">Use de 12 a 128 caracteres. Todos os dispositivos e o WhatsApp vinculado serão desconectados, e seus links privados serão revogados.</p><button class="primary" type="submit">Salvar nova senha e sair</button></form></details></section>`+
 `<section class="card account-privacy" id="privacidade"><span class="eyebrow">PRIVACIDADE</span><h2>Suas autorizações</h2>${consentRow('ai',user.aiConsent,'Mentra IA','Suas perguntas, áudios transcritos e o recorte da sua organização necessário para responder são enviados à DeepSeek, na China, que gera as respostas. Dados de saúde e documentos originais nunca são enviados. Sem esta autorização, a IA fica desligada e o resto do app continua funcionando.')}${consentRow('health',user.healthConsent,'Saúde e bem-estar','Os registros de saúde que você criar (consultas, medicamentos, sono, disposição) ficam guardados na sua conta, só para você. Ao revogar, a área de saúde fica bloqueada. Para apagar os registros, use o botão abaixo.')}${user.healthConsent===false?'':`<button class="outline danger" data-account="erase-health">Apagar meus registros de saúde</button>`}<p class="form-help">Detalhes no <a href="${LEGAL_LINKS.privacy}">Aviso de Privacidade</a>.</p></section>`+
 `<section class="card account-closing" id="encerrar"><span class="eyebrow">PLANO, DADOS E CONTA</span><h2>Encerrar ou apagar</h2><p class="form-help">São quatro ações diferentes. Veja o efeito de cada uma antes de escolher.</p><div class="account-actions-list">`+
 `<details class="account-disclosure"><summary><span>Não renovar o plano<small>Mantém a conta e os dados.</small></span><span aria-hidden="true">＋</span></summary><p>${renewal}</p>${(()=>{const billing=globalThis.mentraPlatform?.billing;if(billing?.autoRenew&&billing.card)return `<p class="account-effect">O cartão ${esc(billing.card.brand||'')} •••• ${esc(billing.card.last4)} renova a assinatura automaticamente${billing.nextCharge?` em ${esc(dateBR(billing.nextCharge.at))}, no valor de ${esc((billing.nextCharge.cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}))}`:''}. Cancelando, nada mais é cobrado e o acesso continua até o fim do período${billing.inTrial?' (no teste grátis, nada é cobrado)':''}.</p><button type="button" class="outline" data-card-action="renew-off">Cancelar renovação automática</button><p id="billing-error" class="form-error" role="alert"></p>`;return `<p class="account-effect">O PIX não renova sozinho e não há cobrança recorrente: não há nada para cancelar. Para continuar depois do fim do período, pague um novo período em Planos.</p>`;})()}</details>`+
 `<details class="account-disclosure"${platform.withdrawal?.eligible?' open':''}><summary><span>Desistir da compra (${LEGAL.withdrawalDays} dias)<small>Direito de arrependimento, art. 49 do CDC.</small></span><span aria-hidden="true">＋</span></summary>${withdrawalMarkup(platform.withdrawal)}</details>`+
 `<details class="account-disclosure account-danger"><summary><span>Apagar meus dados<small>Mantém a conta, o login e o plano.</small></span><span aria-hidden="true">＋</span></summary><p class="account-effect">Efeito: apaga de forma definitiva anotações, tarefas, agenda, finanças, saúde, documentos, conversas, memória da IA e integrações (Google Agenda, WhatsApp, notificações). Ficam a conta, o login, o plano, o histórico de pagamentos e a contagem de mensagens de IA do mês. Os outros aparelhos são desconectados.</p><form id="platform-erase" class="form-stack"><label>Confirme sua senha<input name="password" type="password" autocomplete="current-password" required></label><label class="check-field"><input type="checkbox" name="confirmed" required><span>Entendo que todo o conteúdo será apagado e não poderá ser recuperado.</span></label><button class="outline danger" type="submit">Apagar meus dados</button></form></details>`+
 `<details class="account-disclosure account-danger"><summary><span>Excluir minha conta<small>Exclusão definitiva da conta e dos dados.</small></span><span aria-hidden="true">＋</span></summary><p class="account-effect">Efeito: apaga a conta e todo o conteúdo, encerra as sessões e desconecta as integrações. ${active&&sub.current_period_end?`Os dias pagos até ${esc(dateBR(sub.current_period_end))} se perdem e não são reembolsados${platform.withdrawal?.eligible?'. Você ainda está no prazo de arrependimento: peça “Desistir da compra” antes, se quiser o valor de volta':''}. `:''}Por obrigação fiscal, os registros de pagamento (nome, e-mail, valor, datas) ficam guardados à parte por ${LEGAL.paymentRetentionYears} anos, e os registros de acesso por ${LEGAL.accessLogMonths} meses. Exporte seus dados antes, se quiser uma cópia.</p><form id="platform-delete" class="form-stack"><label>Confirme sua senha<input name="password" type="password" autocomplete="current-password" required></label><label class="check-field"><input type="checkbox" name="confirmed" required><span>Entendo que a conta e todos os meus dados serão excluídos.</span></label><button class="outline danger" type="submit">Excluir conta permanentemente</button></form></details>`+
 `</div><p id="account-error" role="alert" class="form-error"></p></section></div>`+
 `<aside class="account-aside"><section class="card"><span class="eyebrow">SUA ASSINATURA</span><h2>${esc(platform.plans?.find(p=>p.id===sub.plan)?.name||sub.plan)}</h2><p>${esc(subscriptionLabel(sub.status))}${active&&sub.current_period_end?` · até ${esc(dateBR(sub.current_period_end))}`:''}</p><a class="outline full" href="#/planos">Ver meus planos</a></section><section class="card account-backup"><span class="eyebrow">CONTROLE DOS SEUS DADOS</span><h2>Sua cópia, com você</h2><p>Baixe uma cópia da sua organização para restaurar ou exporte todos os dados da conta.</p><button class="primary full" data-account="backup">Baixar cópia para restauração</button><button class="outline full" data-account="export">Exportar meus dados</button><p class="form-help">A exportação completa inclui o histórico das integrações, pagamentos, consentimentos e acessos. A cópia para restauração contém somente sua organização e seus originais.</p><details class="account-disclosure"><summary><span>Restaurar uma cópia</span><span aria-hidden="true">＋</span></summary><label class="restore-upload">Selecionar arquivo JSON<input type="file" data-restore accept=".json,application/json"></label><p class="form-help">Você verá as diferenças antes de confirmar. Assinatura e credenciais não são restauradas.</p></details></section>${aboutMarkup()}</aside></div>`;
}
// App Store 3.1.1 / Google Play payments: native builds never show or start an external checkout.
const storeApp=()=>Boolean(globalThis.mentraNative);
// Decreto nº 7.962/2013: identificação da empresa e resumo das condições junto da oferta, e aceite dos Termos antes do pagamento.
function plansLegalMarkup(paymentsConfigured){const user=globalThis.mentraPlatform?.user;return `<div class="plans-legal">${paymentsConfigured?checkoutSummaryMarkup():''}${paymentsConfigured&&user&&!user.termsAccepted?`<label class="legal-accept"><input type="checkbox" id="plans-accept-terms"><span>Li e aceito os <a href="${LEGAL_LINKS.terms}" target="_blank" rel="noopener">Termos de Uso</a> (versão ${esc(LEGAL.termsVersion)}) e li o <a href="${LEGAL_LINKS.privacy}" target="_blank" rel="noopener">Aviso de Privacidade</a>.</span></label>`:''}${companyMarkup({compact:true})}${legalLinksMarkup()}</div>`;}
export function plansMarkup(subscription,plans=[],usage={},paymentsConfigured=false){if(storeApp())return storePlansMarkup(subscription,plans,usage);const current=plans.find(p=>p.id===subscription.plan),active=subscription.status==='active',granted=active&&!subscription.current_period_end;
 // Paying while active adds the period's days to the current end date (early renewal loses nothing).
 const canPay=p=>paymentsConfigured&&Boolean(planCharge(p))&&!granted;
 const label=p=>canPay(p)?`${active?'Renovar':'Pagar'} com PIX · ${brl(planCharge(p))}`:p.id===subscription.plan?'Plano selecionado':active?'Acesso já liberado':'Selecionar';
 const disabled=p=>paymentsConfigured?!canPay(p):active;
 return `<div class="page-heading"><div><p class="eyebrow">ASSINATURA</p><h1>Seu plano, no seu ritmo.</h1><p>${esc(current?.name||subscription.plan)} · ${esc(subscriptionLabel(subscription.status))}${active&&subscription.current_period_end?` · acesso até ${new Date(subscription.current_period_end).toLocaleDateString('pt-BR')}`:''}</p>${usage.month?`<p>${Number(usage.requests||0).toLocaleString('pt-BR')} de ${Number(current?.monthlyRequests||0).toLocaleString('pt-BR')} mensagens usadas em ${esc(usage.month)}. O ciclo de uso segue o mês em UTC.</p>`:''}</div></div>${(()=>{const platform=globalThis.mentraPlatform,billing=platform?.billing;const card=billingMarkup({billing,plans,subscription,user:platform?.user});return card+(card&&paymentsConfigured?`<h2 class="plans-pix-title">${billing?.trialEligible?'Prefere PIX? Pague agora, sem teste grátis.':'Ou pague com PIX'}</h2><p class="form-help plans-pix-help">O PIX é um pagamento único: libera os dias do período e não renova sozinho.</p>`:'');})()}<div class="portal-plans">${plans.map(p=>`<section class="card ${p.id===subscription.plan?'plan-selected':''}"><h2>${esc(p.name)}</h2>${planPriceMarkup(p)}<p>${esc(p.description)}</p>${p.days?`<p class="plan-days">Cada pagamento libera ${p.days} dias de acesso.</p>`:''}<p>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA/mês</p><button class="${p.id===subscription.plan?'outline':'primary'}" aria-pressed="${p.id===subscription.plan}" data-platform-plan="${p.id}" ${disabled(p)?'disabled':''}>${label(p)}</button></section>`).join('')}</div>${finePrint(plans)}${plansLegalMarkup(paymentsConfigured)}<p class="notice">${paymentsConfigured?`Pagamento via PIX. O pagamento confirmado libera os dias do período escolhido${active&&!granted?', somados ao fim do seu acesso atual':''}. O PIX não renova sozinho; só o cartão tem renovação automática.`:'Os pagamentos serão disponibilizados após a configuração do gateway. Selecionar um plano não gera cobrança nem ativa uma assinatura.'}</p><p id="payment-error" class="form-error" role="alert"></p>${paymentsConfigured?'<section id="payment-pix" class="card pix-panel" aria-live="polite" hidden></section>':''}`;}
function storePlansMarkup(subscription,plans,usage){const current=plans.find(p=>p.id===subscription.plan);return `<div class="page-heading"><div><p class="eyebrow">ASSINATURA</p><h1>Seu plano, no seu ritmo.</h1><p>${esc(current?.name||subscription.plan)} · ${esc(subscriptionLabel(subscription.status))}</p>${usage.month?`<p>${Number(usage.requests||0).toLocaleString('pt-BR')} de ${Number(current?.monthlyRequests||0).toLocaleString('pt-BR')} mensagens usadas em ${esc(usage.month)}.</p>`:''}</div></div><div class="portal-plans">${plans.map(p=>`<section class="card ${p.id===subscription.plan?'plan-selected':''}" data-store-plan="${esc(p.id)}"><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p>${p.days?`<p>${p.days} dias de acesso completo</p>`:''}<p>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA/mês</p>${p.id===subscription.plan?'<p class="eyebrow">SEU PLANO</p>':''}</section>`).join('')}</div><p class="notice">A assinatura não é contratada pelo aplicativo, nem pela App Store ou pelo Google Play, e não renova sozinha. Quando ela está ativa na sua conta Mentra, todos os recursos do plano ficam disponíveis aqui automaticamente.</p><div class="plans-legal">${companyMarkup({compact:true,links:false})}<p class="form-help">Termos de Uso e Aviso de Privacidade em Meu espaço → Sobre e contato.</p></div>`;}
